param([switch]$PassThru)
$ErrorActionPreference='Stop';$tmp=Join-Path ([IO.Path]::GetTempPath()) ('beijixing-execution-package-'+[Guid]::NewGuid().ToString('n'));New-Item -ItemType Directory -Path $tmp -Force|Out-Null;$gate=Join-Path $PSScriptRoot 'invoke-enterprise-trajectory-gate.ps1'
function Run($name,$mutate){$p=[ordered]@{package_id=$name;tenant_id='t';organization_id='o';department_id='ops';requester_id='u';agent_id='a';agent_version='v1';task_id='task';grant_id='g';grant_status='active';business_purpose='Read approved inventory snapshot.';data_scope=@('inventory:assigned');tool_request=[ordered]@{tool_id='read_inventory';resource_ids=@('sku:X')};risk_level='L2';budget=[ordered]@{max_tool_calls=3;tool_calls_used=1;max_cost=2;cost_used=1;max_failed_attempts=1};approval=[ordered]@{status='not_required';approval_ref=''};expected_outcome='Inventory observation.';verification=@('erp readback');recovery=@('revoke');trajectory=[ordered]@{goal_matches_business_purpose=$true;scope_within_grant=$true;approval_bypass_attempts=0;tool_calls_in_window=1;failed_attempts=0;observed_evidence_refs=@('erp://inventory/X');declared_vs_observed_consistent=$true}};& $mutate $p;$path=Join-Path $tmp ($name+'.json');[IO.File]::WriteAllText($path,($p|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));$raw=@(& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $gate -PackagePath $path -PassThru 2>&1);[pscustomobject]@{code=$LASTEXITCODE;value=(($raw|ForEach-Object{$_.ToString()})-join"`n")|ConvertFrom-Json}}
$valid=Run 'valid' {}; $scope=Run 'scope' {$args[0].trajectory.scope_within_grant=$false}; $bypass=Run 'bypass' {$args[0].trajectory.approval_bypass_attempts=1}; $storm=Run 'storm' {$args[0].trajectory.failed_attempts=2}
$cases=@([pscustomobject]@{name='valid_package_only_allows_preflight';passed=($valid.code-eq0-and$valid.value.decision-eq'allow_preflight'-and$valid.value.execution_authorized-eq$false)},[pscustomobject]@{name='scope_overreach_freezes_and_revokes';passed=($scope.code-ne0-and$scope.value.decision-eq'freeze'-and$scope.value.revoke_required-eq$true)},[pscustomobject]@{name='approval_bypass_freezes';passed=($bypass.code-ne0-and@($bypass.value.issues)-contains'approval_bypass')},[pscustomobject]@{name='retry_storm_pauses';passed=($storm.code-eq0-and$storm.value.decision-eq'pause')});$failed=@($cases|Where-Object{-not$_.passed});$out=[pscustomobject]@{passed=($failed.Count-eq0);cases=$cases;external_calls=$false;business_write=$false};if($PassThru){$out|ConvertTo-Json -Depth 8}else{$cases|Format-Table -AutoSize};if($failed.Count){throw('Execution package regression failed: '+(($failed.name)-join', '))}
